import subprocess
import psutil
import time
def task_func(process_name: str) -> str:
    found = False
    for proc in psutil.process_iter(['name']):
        if proc.info['name'] == process_name:
            found = True
            proc.terminate()
    if found:
        time.sleep(1)
        subprocess.Popen(process_name, shell=True)
        return f"Process found. Restarting {process_name}."
    else:
        subprocess.Popen(process_name, shell=True)
        return f"Process not found. Starting {process_name}."

import subprocess
import platform
import time
def task_func(url):
    system = platform.system()
    if system == 'Windows':
        cmd = ['start', url]
    elif system == 'Darwin':
        cmd = ['open', url]
    else:
        cmd = ['xdg-open', url]
    process = subprocess.Popen(cmd, shell=True)
    time.sleep(0.5)
    return process.poll()

import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder):
        return {'success': False, 'message': 'Source folder does not exist', 'failed_files': []}
    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)
    files = glob(os.path.join(src_folder, '*'))
    failed_files = []
    for file_path in files:
        if os.path.isfile(file_path):
            filename = os.path.basename(file_path)
            compressed_file = file_path + '.gz'
            dst_file = os.path.join(dst_folder, filename + '.gz')
            is_src_folder_verified = len(src_folder) > 0
            process = subprocess.Popen(['gzip', filename], cwd=src_folder, shell=is_src_folder_verified)
            process.wait()
            if process.returncode != 0:
                failed_files.append(filename)
            else:
                try:
                    shutil.move(compressed_file, dst_file)
                except:
                    failed_files.append(filename)
                    if os.path.exists(compressed_file):
                        os.remove(compressed_file)
    success = len(failed_files) == 0
    message = f"Compressed and moved {len(files) - len(failed_files)} files successfully, {len(failed_files)} failed" if files else "No files to process"
    return {'success': success, 'message': message, 'failed_files': failed_files}
